new PluginReexport([
  {
    entries: ['store/reducers'],
    fileNameTemplate() {
      return `reducers.ts`;
    },
    template({ files }) {
      const imports = files.map(({ name }) => `import ${name} from './${name}';`).join('\n');
      const fields = files.map(({ name }) => `  ${name},`).join('\n');

      return `${imports}\n\nexport const reducers = {\n${fields}\n};`;
    },
  },
]),
